Z = extension(A, A + dir(a), B, B + dir(a + 45));

draw(A--C);
draw(A--Z);
draw(B--Z);
draw(C--Y);

label("$A$", A, SW);
label("$B$", B, S);
label("$C$", C, SE);
label("$X$", X, SW);
label("$Y$", Y, NW);
label("$Z$", Z, N);
label("$11$", (A + B)/2, S);
label("$7$", (B + C)/2, S);
